import { useState, createContext, useContext } from 'react';

// TODO: Create TabsContext
const TabsContext = createContext(null);

function useTabs() {
  const ctx = useContext(TabsContext);
  if (!ctx) throw new Error('Tab components must be inside <Tabs>');
  return ctx;
}

// TODO: Tabs root component — owns state, provides context
function Tabs({ children, defaultTab }) {
  const [activeTab, setActiveTab] = useState(defaultTab);
  return (
    <TabsContext.Provider value={{ activeTab, setActiveTab }}>
      <div data-testid="tabs">{children}</div>
    </TabsContext.Provider>
  );
}

// TODO: Tabs.List — role=tablist
Tabs.List = function TabList({ children }) {
  return <div role="tablist" data-testid="tab-list">{children}</div>;
};

// TODO: Tabs.Tab — role=tab, aria-selected, onClick
Tabs.Tab = function Tab({ id, children }) {
  const { activeTab, setActiveTab } = useTabs();
  return (
    <button
      role="tab"
      aria-selected={activeTab === id}
      onClick={() => setActiveTab(id)}
      data-testid={`tab-${id}`}
    >
      {children}
    </button>
  );
};

// TODO: Tabs.Panel — role=tabpanel, only renders when active
Tabs.Panel = function TabPanel({ id, children }) {
  const { activeTab } = useTabs();
  return activeTab === id
    ? <div role="tabpanel" data-testid={`panel-${id}`}>{children}</div>
    : null;
};

export default function App() {
  return (
    <div data-testid="app">
      <Tabs defaultTab="quests">
        <Tabs.List>
          <Tabs.Tab id="quests">Quests</Tabs.Tab>
          <Tabs.Tab id="members">Members</Tabs.Tab>
        </Tabs.List>
        <Tabs.Panel id="quests">Quest Board Content</Tabs.Panel>
        <Tabs.Panel id="members">Member List Content</Tabs.Panel>
      </Tabs>
    </div>
  );
}
